<?php
require_once __DIR__.'/core/Auth.php';bo_require_login();
require_once __DIR__.'/core/ApiClient.php';
require_once __DIR__.'/core/Payroll.php';
require_once __DIR__.'/core/Company.php';
$month=(string)($_GET['month']??date('Y-m'));if(!bo_payroll_valid_month($month))$month=date('Y-m');
$assignmentId=(int)($_GET['assignment_id']??0);$boUserId=(int)($_GET['bo_user_id']??0);if($assignmentId<=0&&$boUserId<=0){http_response_code(400);exit('Pegawai tidak valid.');}
$run=bo_payroll_run($month);$locked=$run&&in_array((string)($run['status']??''),['final','paid'],true);$item=null;
if($locked){foreach((array)($run['items']??[]) as $it){if(($assignmentId>0&&(int)($it['assignment_id']??0)===$assignmentId)||($boUserId>0&&(int)($it['bo_user_id']??0)===$boUserId)){$item=$it;if(!empty($it['snapshot_json'])){$sj=json_decode((string)$it['snapshot_json'],true);if(is_array($sj))$item=array_merge($it,$sj);}break;}}}
else{$calc=bo_payroll_compute($month);foreach($calc['items'] as $it){if(($assignmentId>0&&(int)($it['assignment_id']??0)===$assignmentId)||($boUserId>0&&(int)($it['bo_user_id']??0)===$boUserId)){$item=$it;break;}}}
if(!$item){http_response_code(404);exit('Data payroll pegawai tidak ditemukan untuk periode ini.');}
$name=(string)($item['employee_name']??$item['employee_name_snapshot']??'-');$role=(string)($item['role_key']??$item['role_key_snapshot']??'-');$unit=(string)($item['unit_name']??$item['unit_name_snapshot']??'-');
$gross=(float)($item['incentive_gross']??$item['incentive_amount']??$item['incentive']??0);$leave=(float)($item['leave_deduction']??0);$late=(float)($item['late_early_deduction']??0);$redis=(float)($item['incentive_redistributed']??0);$finalIncentive=(float)($locked?($item['incentive_amount']??0):($item['incentive']??0));
$otherDed=(float)($item['bpjs_kesehatan']??0)+(float)($item['bpjs_ketenagakerjaan']??0)+(float)($item['pph21']??0)+(float)($item['punishment']??0)+(float)($item['kasbon']??0);$income=(float)($item['base_salary']??0)+(float)($item['overtime']??0)+(float)($item['admin_share']??0)+$finalIncentive;$thp=(float)($item['take_home']??max(0,$income-$otherDed));
$months=['01'=>'Januari','02'=>'Februari','03'=>'Maret','04'=>'April','05'=>'Mei','06'=>'Juni','07'=>'Juli','08'=>'Agustus','09'=>'September','10'=>'Oktober','11'=>'November','12'=>'Desember'];[$yy,$mm]=explode('-',$month);$period=($months[$mm]??$mm).' '.$yy;
$company=bo_company_name();$logoData='';$lp=bo_company_logo_path();if($lp){$mime=(string)(mime_content_type($lp)?:'image/png');$logoData='data:'.$mime.';base64,'.base64_encode((string)file_get_contents($lp));}
function slip_money($v){return 'Rp '.number_format((float)$v,0,',','.');}
