<section class="cols"><div class="box"><h3>A. Pendapatan</h3><table><tr><td>Gaji Pokok</td><td><?=slip_money($item['base_salary']??0)?></td></tr><tr><td>Lembur</td><td><?=slip_money($item['overtime']??0)?></td></tr><?php if((float)($item['admin_share']??0)>0): ?><tr><td>Bagian Admin</td><td><?=slip_money($item['admin_share'])?></td></tr><?php endif; ?><tr><td>Insentif Final</td><td><?=slip_money($finalIncentive)?></td></tr><tr class="total"><td>Total Pendapatan</td><td><?=slip_money($income)?></td></tr></table></div><div class="box"><h3>B. Potongan Non-Insentif</h3><table><tr><td>BPJS Kesehatan</td><td><?=slip_money($item['bpjs_kesehatan']??0)?></td></tr><tr><td>BPJS Ketenagakerjaan</td><td><?=slip_money($item['bpjs_ketenagakerjaan']??0)?></td></tr><tr><td>PPh 21</td><td><?=slip_money($item['pph21']??0)?></td></tr><tr><td>Punishment</td><td><?=slip_money($item['punishment']??0)?></td></tr><tr><td>Kasbon</td><td><?=slip_money($item['kasbon']??0)?></td></tr><tr class="total"><td>Total Potongan</td><td><?=slip_money($otherDed)?></td></tr></table></div></section>
<div class="thp"><span>TAKE HOME PAY (THP)</span><span><?=slip_money($thp)?></span></div>
<section class="detail"><table><thead><tr><th colspan="3">Rincian Penyesuaian Insentif</th></tr><tr><th>Keterangan</th><th>Dasar</th><th>Nominal</th></tr></thead><tbody><tr><td>Insentif awal</td><td>Sebelum koreksi cuti/keterlambatan</td><td><?=slip_money($gross)?></td></tr><tr><td>Pengurangan karena cuti</td><td><?=e(number_format((float)($item['leave_days']??0),2,',','.'))?> hari / target <?=e(number_format((float)($item['leave_target_workdays']??0),2,',','.'))?> hari</td><td>- <?=slip_money($leave)?></td></tr><tr><td>Pengurangan terlambat / pulang cepat</td><td><?=e((string)($item['late_early_notes']??'-'))?></td><td>- <?=slip_money($late)?></td></tr><tr><td>Redistribusi insentif diterima</td><td>Redistribusi dari pool unit</td><td>+ <?=slip_money($redis)?></td></tr><tr class="total"><td colspan="2">Insentif Final</td><td><?=slip_money($finalIncentive)?></td></tr></tbody></table></section>
